add_filter( 'storefront_copyright_text', 'perfectpixel_storefront_copyright' );
add_filter( 'storefront_credit_link', 'perfectpixel_storefront_no_credit_link' );
add_filter( 'storefront_privacy_policy_link', 'perfectpixel_storefront_privacy_link' );

function perfectpixel_storefront_copyright() {
	return esc_html( str_replace( '{year}', wp_date( 'Y' ), '{{storefront_copyright}}' ) );
}

function perfectpixel_storefront_no_credit_link() {
	return false;
}

function perfectpixel_storefront_privacy_link( $show ) {
	return 'yes' === '{{storefront_keep_privacy}}' ? $show : false;
}
